INSERT INTO `chat_session` VALUES ('2054521018593239041:31a003af-169e-4b52-bfdf-d837b728d02b', 2054521018593239041, 'travel_manus', '31a003af-169e-4b52-bfdf-d837b728d02b', '我是谁', '你好呀～我是行旅 AI，专注帮你规划国内旅行：比如定制轻松又好玩的行程、推荐地道美食和高性价比住宿、估算靠谱预算，还有交通路线、天气提醒这些实用信息。 你最近有想去的地方吗？比如城市、景点，或者大概出行时间、天数、几个人一起？告诉我这些，我马上为你搭一个贴心又落地的出游方案 😊', '2026-05-25 13:25:36', '2026-05-25 13:25:36');
INSERT INTO `chat_session` VALUES ('2054521018593239041:3cff721c-6a4d-4aef-ba66-f67a10ce3375', 2054521018593239041, 'travel_app', '3cff721c-6a4d-4aef-ba66-f67a10ce3375', '你好', '你好，杨严！ 不过需要说明的是：你提供的上下文内容，是关于「恋爱中如何温和沟通对方缺点」的沟通技巧示例和课程推荐（如《恋爱中缺点沟通与关系优化》），属于亲密关系咨询范畴。 而我的角色是【行旅 AI - 新中式国风旅游咨询助手】，专注为国内文旅目的地提供专业、真实、有审美感的旅行建议，例如： - 哪些古镇/园林/山水地最适合汉服出行、慢游拍照？ - 某地有哪些地道非遗体验、节气美食、中式民宿？ - 如何避开商业化雷区、选对交通住宿、穿得得体又自在？ - 国风旅行中的礼仪分寸、应急提醒、文化小常识…… 如果你', '2026-05-25 13:26:15', '2026-05-25 13:26:25');
INSERT INTO `chat_session` VALUES ('2054521018593239041:6e047cb6-aa9f-4139-a412-878012ef5841', 2054521018593239041, 'travel_manus', '6e047cb6-aa9f-4139-a412-878012ef5841', '你好，我是杨严', '你好，杨严！很高兴认识你～ 我是你的国内旅游规划助手，可以帮你： ✅ 规划城市深度游/周边短途游行程（比如成都4天怎么玩、苏州3日怎么逛） ✅ 推荐地道美食、小众景点、舒适住宿和靠谱交通方式 ✅ 估算真实预算（含门票、吃住、市内交通等） ✅ 查询实时天气、景区开放时间、最新政策提醒 你最近有想去的地方吗？比如： 📍 目的地（如“大理”“西安”“厦门”） 📅 出行时间 & 天数（如“五一假期5天”“暑假带娃10天”） 👥 出行人数 & 偏好（如“2人情侣游”“一家四口亲子”“喜欢拍照/爱逛博物馆/专程', '2026-05-25 13:20:54', '2026-05-25 13:25:02');
INSERT INTO `chat_session` VALUES ('2054521018593239041:8c60e95a-8cb6-4c80-976c-b709a4b6714e', 2054521018593239041, 'travel_app', '8c60e95a-8cb6-4c80-976c-b709a4b6714e', '我是谁', '你是在开启一段对话，带着一点哲思或俏皮的自我探寻意味——“我是谁”这个问题，本身就很中式、很人文，像一句禅机，也像一次旅行前的内心叩问。 不过，根据当前提供的上下文信息，里面并没有关于你个人身份、背景、所在地或具体特征的任何描述。它只反复强调了一套通用的社交技巧（微笑、找话题、真诚倾听、推荐课程等），但并未指向“你是谁”这个具体问题的答案。 所以，如实相告： **当前资料中没有关于“你是谁”的识别信息。** 你可能是热爱国风旅行的朋友，也可能是正在为下一次出行做准备的旅人，或是对文化体验、审美表达有追求的', '2026-05-25 13:26:39', '2026-05-25 13:26:39');
INSERT INTO `chat_session` VALUES ('2054521018593239041:acd938ef-a0c4-498e-8657-462cef978835', 2054521018593239041, 'travel_manus', 'acd938ef-a0c4-498e-8657-462cef978835', '你好我是张三', '你好张三！很高兴认识你～我是行旅 AI，专门帮你规划国内旅行，比如定制行程、推荐小众玩法、查实时天气和交通、估算预算，或者帮你找地道美食和舒适住宿。 想问问你：最近有想去的地方吗？比如城市、景点，或者有没有大致的出行时间、天数、几个人一起，还有偏好的风格（比如轻松逛吃、亲子友好、爱拍照打卡，或者想深度体验本地生活）？告诉我这些，我马上为你量身安排 🌟', '2026-05-25 13:25:28', '2026-05-25 13:25:28');
